 using Contoso.Text;

 namespace StringFormatterTests;

 [TestClass]
 public sealed class FormatPhoneNumberTests
 {
     private readonly StringFormatter _formatter = new();

     [TestMethod]
     public void ValidDigits_ReturnsFormattedNumber()
     {
         var result = _formatter.FormatPhoneNumber("1234567890");

         Assert.AreEqual("(123) 456-7890", result);
     }

     [TestMethod]
     public void FormattedNumber_StartsWithAreaCodeInParens()
     {
         var result = _formatter.FormatPhoneNumber("8005551234");

         StringAssert.StartsWith(result, "(800)");
     }

     [TestMethod]
     public void FormattedNumber_EndsWithLastFourDigits()
     {
         var result = _formatter.FormatPhoneNumber("8005551234");

         StringAssert.EndsWith(result, "1234");
     }

     [TestMethod]
     public void FormattedNumber_ContainsDashSeparator()
     {
         var result = _formatter.FormatPhoneNumber("8005551234");

         StringAssert.Contains(result, "-");
     }

     [TestMethod]
     public void FormattedNumber_MatchesPattern()
     {
         var result = _formatter.FormatPhoneNumber("8005551234");

         StringAssert.Matches(result, new(@"^\(\d{3}\) \d{3}-\d{4}$"));
     }

     [TestMethod]
     public void NullDigits_ThrowsArgumentNullException()
     {
         Assert.ThrowsExactly<ArgumentNullException>(() => _formatter.FormatPhoneNumber(null!));
     }

     [TestMethod]
     [DataRow("123")]
     [DataRow("12345678901")]
     [DataRow("")]
     public void WrongLength_ThrowsArgumentException(string digits)
     {
         Assert.ThrowsExactly<ArgumentException>(() => _formatter.FormatPhoneNumber(digits));
     }
 }

 [TestClass]
 public sealed class BuildGreetingTests
 {
     private readonly StringFormatter _formatter = new();

     [TestMethod]
     public void DefaultTitle_ReturnsGreetingWithMr()
     {
         var result = _formatter.BuildGreeting("Smith");

         Assert.AreEqual("Dear Mr. Smith,", result);
     }

     [TestMethod]
     public void Greeting_StartsWithDear()
     {
         var result = _formatter.BuildGreeting("Jones", "Dr.");

         StringAssert.StartsWith(result, "Dear");
     }

     [TestMethod]
     public void Greeting_EndsWithComma()
     {
         var result = _formatter.BuildGreeting("Jones", "Dr.");

         StringAssert.EndsWith(result, ",");
     }

     [TestMethod]
     public void CustomTitle_ContainsTitle()
     {
         var result = _formatter.BuildGreeting("Jones", "Dr.");

         StringAssert.Contains(result, "Dr.");
     }

     [TestMethod]
     public void Greeting_ContainsName()
     {
         var result = _formatter.BuildGreeting("Jones");

         StringAssert.Contains(result, "Jones");
     }

     [TestMethod]
     public void NullName_ThrowsArgumentNullException()
     {
         Assert.ThrowsExactly<ArgumentNullException>(() => _formatter.BuildGreeting(null!));
     }

     [TestMethod]
     [DataRow("")]
     [DataRow("   ")]
     public void EmptyOrWhitespaceName_ThrowsArgumentException(string name)
     {
         Assert.ThrowsExactly<ArgumentException>(() => _formatter.BuildGreeting(name));
     }
 }

 [TestClass]
 public sealed class GenerateSlugTests
 {
     private readonly StringFormatter _formatter = new();

     [TestMethod]
     public void SimpleTitle_ReturnsLowercaseDashSeparated()
     {
         var result = _formatter.GenerateSlug("Hello World");

         Assert.AreEqual("hello-world", result);
     }

     [TestMethod]
     public void Slug_DoesNotStartWithDash()
     {
         var result = _formatter.GenerateSlug("  Hello World  ");

         StringAssert.DoesNotMatch(result, new(@"^-"));
     }

     [TestMethod]
     public void Slug_DoesNotEndWithDash()
     {
         var result = _formatter.GenerateSlug("  Hello World  ");

         StringAssert.DoesNotMatch(result, new(@"-$"));
     }

     [TestMethod]
     public void SpecialCharacters_ReplacedWithDashes()
     {
         var result = _formatter.GenerateSlug("C# is Great!!!");

         Assert.AreEqual("c-is-great", result);
     }

     [TestMethod]
     public void MixedCase_AllLowercase()
     {
         var result = _formatter.GenerateSlug("MSTest Is Fun");

         StringAssert.Matches(result, new(@"^[a-z0-9\-]+$"));
     }

     [TestMethod]
     public void NullTitle_ThrowsArgumentNullException()
     {
         Assert.ThrowsExactly<ArgumentNullException>(() => _formatter.GenerateSlug(null!));
     }

     [TestMethod]
     [DataRow("")]
     [DataRow("   ")]
     public void EmptyOrWhitespaceTitle_ThrowsArgumentException(string title)
     {
         Assert.ThrowsExactly<ArgumentException>(() => _formatter.GenerateSlug(title));
     }
 }

 [TestClass]
 public sealed class FormatCurrencyTests
 {
     private readonly StringFormatter _formatter = new();

     [TestMethod]
     public void DefaultSymbol_StartsWithDollarSign()
     {
         var result = _formatter.FormatCurrency(19.99m);

         StringAssert.StartsWith(result, "$");
     }

     [TestMethod]
     public void CustomSymbol_StartsWithSymbol()
     {
         var result = _formatter.FormatCurrency(19.99m, "€");

         StringAssert.StartsWith(result, "€");
     }

     [TestMethod]
     public void WholeNumber_EndsWithTwoDecimalPlaces()
     {
         var result = _formatter.FormatCurrency(100m);

         StringAssert.EndsWith(result, ".00");
     }

     [TestMethod]
     public void FormatsToTwoDecimalPlaces()
     {
         var result = _formatter.FormatCurrency(9.9m);

         Assert.AreEqual("$9.90", result);
     }

     [TestMethod]
     public void NegativeAmount_ContainsMinusSign()
     {
         var result = _formatter.FormatCurrency(-5.50m);

         StringAssert.Contains(result, "-");
     }

     [TestMethod]
     public void ZeroAmount_ReturnsZeroFormatted()
     {
         var result = _formatter.FormatCurrency(0m);

         Assert.AreEqual("$0.00", result);
     }
 }
